 function setView(camera){if(engineOptions.detail==='full')return;camera.updateMatrixWorld();root.updateWorldMatrix(true,false);const frustum=new T.Frustum().setFromProjectionMatrix(new T.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse));for(const [p,members]of corePenMembers){const center=root.localToWorld(new T.Vector3(p.world.x,heightAt(p.world.x,p.world.z)+2,p.world.z)),scale=root.getWorldScale(new T.Vector3()).x,radius=Math.hypot(p.w,p.d,6)*.5*scale;const visible=frustum.intersectsSphere(new T.Sphere(center,radius));for(const actor of members)actor.detail=visible||actor.a.loose?'full':'coarse';}}
 const coreWorkers=workers.map(w=>attachPerson(w));
