 const coreContext={state,actors:coreActors,workers:coreWorkers,homes,home,places,pens,rng,decisions,poiOccupancy,farmhandProfiles,carryAvailable:!!carryTemplates,obstacles,inBoard,heightAt,outsideEntry,assembly,starterChild,advisors,penMembers:corePenMembers,recipe,poiPlaces,poiNeighbors,inside,source,network,poseOwnership,animalRadius,penObstacles,inPen,station,compiled,bench:bench?{x:bench.position.x,z:bench.position.z}:null,get layoutVersion(){return layoutVersion;},set layoutVersion(value){layoutVersion=value;}};
 const core=createRanchCore(coreContext);ecology.useModel(core.ecology);
 function syncViews(force=false){
  for(const w of [...workers])if(!coreWorkers.includes(w.core)){root.remove(w.body);workers.splice(workers.indexOf(w),1);}
  for(const actor of coreWorkers){let w=workers.find(w=>w.core===actor);if(!w){const body=makePerson(actor.person);body.userData.noInk=true;const waterCarry=carryTemplates.water.clone(),feedCarry=carryTemplates.feed.clone();body.add(waterCarry,feedCarry);root.add(body);w={body,waterCarry,feedCarry};attachPerson(w,actor);workers.push(w);}
   if(!force&&poseOwnership.owns(humanId(w)))continue;w.body.visible=actor.body.visible;w.body.rotation.y=actor.body.rotation.y;w.body.position.copy(actor.body.position);w.body.scale.copy(actor.body.scale);Object.assign(w.body.userData,actor.body.userData);w.waterCarry.visible=actor.waterCarry.visible;w.feedCarry.visible=actor.feedCarry.visible;
   const a=actor.animation;if(a&&w.body.visible)animateRanchPerson(w,a.state,a.distance,a.dt,heightAt);if(actor.workGesture){const g=actor.workGesture;w.body.userData.limbs[0].rotation.x=g.left;w.body.userData.limbs[2].rotation.x=g.right;w.body.userData.head.rotation.x=g.head;}
  }
  for(const v of animalViews){if(!force&&poseOwnership.owns(animalId(v)))continue;const actor=v.core;v.body.position.copy(actor.body.position);v.body.rotation.y=actor.body.rotation.y;v.body.scale.copy(actor.body.scale);if(actor.detail==='full'&&actor.animation){const a=actor.animation;v.rig.update(a.distance,a.dt,a.activity,v.slot*7);}v.body.userData.storyId=v.a.storyId;v.body.userData.liveReadout=()=>`${v.a.activity} · age ${Number.isFinite(v.a.age)?v.a.age.toFixed(1):'—'} · generation ${v.a.generation} · size ${v.a.traits?.size??1} · pace ${v.a.traits?.pace??1} · hunger ${Math.round(v.a.hunger*100)}% · thirst ${Math.round(v.a.thirst*100)}%`;}
 }
